"""AVL-tree-backed sorted map. Stdlib only."""


class _Node:
    __slots__ = ("key", "value", "left", "right", "height")

    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.left = None
        self.right = None
        self.height = 1  # leaf height


class AVLMap:
    """Sorted map keyed by comparable keys, backed by a self-balancing AVL tree."""

    def __init__(self):
        self._root = None
        self._size = 0

    # ------------------------------------------------------------------ #
    # Public API
    # ------------------------------------------------------------------ #

    def __len__(self):
        return self._size

    def insert(self, key, value):
        """Insert or update; returns the previous value for `key` or None."""
        old = [None]
        self._root = self._insert(self._root, key, value, old)
        return old[0]

    def get(self, key, default=None):
        node = self._root
        while node is not None:
            if key == node.key:
                return node.value
            node = node.left if key < node.key else node.right
        return default

    def __contains__(self, key):
        node = self._root
        while node is not None:
            if key == node.key:
                return True
            node = node.left if key < node.key else node.right
        return False

    def delete(self, key):
        """Remove `key`. Raises KeyError if absent. Returns removed value."""
        removed = [None]
        self._root = self._delete(self._root, key, removed)
        return removed[0]

    def min_key(self):
        if self._root is None:
            raise KeyError("min_key() on empty AVLMap")
        return self._min_node(self._root).key

    def max_key(self):
        if self._root is None:
            raise KeyError("max_key() on empty AVLMap")
        node = self._root
        while node.right is not None:
            node = node.right
        return node.key

    def items(self):
        """In-order (sorted by key) list of (key, value) pairs."""
        out = []

        def walk(node):
            stack = []
            while stack or node is not None:
                while node is not None:
                    stack.append(node)
                    node = node.left
                node = stack.pop()
                out.append((node.key, node.value))
                node = node.right

        walk(self._root)
        return out

    # ------------------------------------------------------------------ #
    # Internal helpers
    # ------------------------------------------------------------------ #

    @staticmethod
    def _h(node):
        return node.height if node is not None else 0

    @classmethod
    def _update(cls, node):
        node.height = 1 + max(cls._h(node.left), cls._h(node.right))

    @classmethod
    def _balance_factor(cls, node):
        return cls._h(node.left) - cls._h(node.right)

    @staticmethod
    def _rotate_right(y):
        x = y.left
        y.left = x.right
        x.right = y
        _Node.__setattr__  # noqa: B018  (no-op; keep linters honest)
        AVLMap._update(y)
        AVLMap._update(x)
        return x

    @staticmethod
    def _rotate_left(x):
        y = x.right
        x.right = y.left
        y.left = x
        AVLMap._update(x)
        AVLMap._update(y)
        return y

    @classmethod
    def _rebalance(cls, node):
        cls._update(node)
        bf = cls._balance_factor(node)
        if bf > 1:  # left-heavy
            if cls._balance_factor(node.left) < 0:  # LR case
                node.left = cls._rotate_left(node.left)
            node = cls._rotate_right(node)  # LL case
        elif bf < -1:  # right-heavy
            if cls._balance_factor(node.right) > 0:  # RL case
                node.right = cls._rotate_right(node.right)
            node = cls._rotate_left(node)  # RR case
        return node

    def _insert(self, node, key, value, old_out):
        if node is None:
            self._size += 1
            return _Node(key, value)
        if key == node.key:
            old_out[0] = node.value
            node.value = value
            return node
        if key < node.key:
            node.left = self._insert(node.left, key, value, old_out)
        else:
            node.right = self._insert(node.right, key, value, old_out)
        return self._rebalance(node)

    @staticmethod
    def _min_node(node):
        while node.left is not None:
            node = node.left
        return node

    def _delete(self, node, key, removed_out):
        if node is None:
            raise KeyError(key)
        if key < node.key:
            node.left = self._delete(node.left, key, removed_out)
        elif key > node.key:
            node.right = self._delete(node.right, key, removed_out)
        else:
            removed_out[0] = node.value
            self._size -= 1
            if node.left is None:
                return node.right
            if node.right is None:
                return node.left
            # Two children: replace with in-order successor.
            succ = self._min_node(node.right)
            node.key, node.value = succ.key, succ.value
            node.right = self._delete_successor(node.right, succ.key)
        return self._rebalance(node)

    def _delete_successor(self, node, key):
        if node.key == key:
            return node.right
        node.left = self._delete_successor(node.left, key)
        return self._rebalance(node)

    # ------------------------------------------------------------------ #
    # Invariant checking
    # ------------------------------------------------------------------ #

    def _check_invariants(self):
        """Walk the tree asserting BST order, stored-height correctness,
        and balance factor in {-1, 0, +1}. Returns node count."""

        def check(node, lo, hi):
            if node is None:
                return 0
            assert lo < node.key < hi, (
                f"BST order violated at key {node.key!r} "
                f"(bounds {lo!r}, {hi!r})"
            )
            hl = check(node.left, lo, node.key)
            hr = check(node.right, node.key, hi)
            expected_h = 1 + max(hl, hr)
            assert node.height == expected_h, (
                f"stale height at key {node.key!r}: "
                f"stored {node.height}, actual {expected_h}"
            )
            bf = hl - hr
            assert bf in (-1, 0, 1), (
                f"AVL balance violated at key {node.key!r}: bf={bf}"
            )
            return expected_h

        n = check(self._root, float("-inf"), float("inf"))
        assert len(self) == n, f"size field {self._size} != nodes {n}"
        return n

